scwin.vScrenID = "ULDINS05600.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
/********************************************** 
 * 함수명   : ins_search
 * 설명       : 발행기관 변경접수 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05600_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.listCorpIssInstEditRctInquiry";
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

};

/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 발행기관 변경접수 상세  조회한다.
 ***********************************************/
scwin.ins_bf_detail = function(ISUR_CD, ISUR_APPL_ID) {
    // 이전 발행기관 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05600_BF_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpBfIssInstEditRctView" + "&{P}param01=" + ISUR_CD;
    dts_bf_detail.DataID = encodeURI(url);
    dts_bf_detail.reset();
};



/********************************************** 
 * 함수명   : ins_detail
 * 설명       : 발행기관 변경접수 상세  조회한다.
 ***********************************************/
scwin.ins_af_detail = function(ISUR_CD, ISUR_APPL_ID) {
    // 이후 발행기관 
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05600_AF_DETAIL_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.readCorpAfIssInstEditRctView" + "&{P}param01=" + ISUR_CD + "&{P}param02=" + ISUR_APPL_ID;
    dts_af_detail.DataID = encodeURI(url);
    dts_af_detail.reset();
};
scwin.ins_detail = function(ISUR_CD, ISUR_APPL_ID) {
    bnd_af_detail.ClearData();
    bnd_bf_detail.ClearData();
};


/********************************************** 
 * 함수명   : checkCoNm
 * 설명       : 발행기관 코드에 따른 조회한다.
 * 상호 변경한 기관의 유가증권 중 활성상태인 표준코드를 발견했습니다
 ***********************************************/
scwin.checkCoNm = function(ISUR_CD) {
    //alert("=========> "+ISUR_CD);
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS05600_CHECKCONM_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.checkCoNm" + "&{P}ISUR_CD=" + ISUR_CD;
    dts_checkCoNm.DataID = encodeURI(url);
    dts_checkCoNm.reset();
};

/********************************************** 
 * 함수명   : ins_register
 * 설명       : 발행기관 변경접수 등록한다.
 ***********************************************/
scwin.ins_register = function() {
    if (!$c.cp.isModified(dts_af_detail)) {
        //alert("변경된 데이터가 없습니다."); 

        //return;

    }
    if (txb_ISUR_NM.getValue() == "" || txb_ISUR_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관명"));
        txb_ISUR_NM.focus();
        return;
    }
    if (txb_ISUR_ABBRV.getValue() == "" || txb_ISUR_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관약명"));
        txb_ISUR_ABBRV.focus();
        return;
    }
    if (txb_ISUR_ENG_NM.getValue() == "" || txb_ISUR_ENG_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관(EN)"));
        txb_ISUR_ENG_NM.focus();
        return;
    }
    if (txb_ISUR_ENG_ABBRV.getValue() == "" || txb_ISUR_ENG_ABBRV.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "발행기관약명(EN)"));
        txb_ISUR_ENG_ABBRV.focus();
        return;
    }

    /* 결산월 control */
    var cmb_ChkCnt = 0;
    var tmpCnt = 0;
    var tmpAcntMM = new Array();
    for (var i = 1; i <= 12; i++) {
        if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == "") {
            cmb_ChkCnt = cmb_ChkCnt + 1;
        }
    }
    if (cmb_ChkCnt == 12) {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "결산월"));
        cmb_ACNTCLS_MM1.focus();
        return;
    }
    for (var i = 1; i <= 12; i++) {
        for (var j = 12; j >= 1; j--) {
            if (i != j) {
                if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + j) != "") {
                        if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i) == dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + j)) {
                            $c.win.alert("동일한 결산월이 존재합니다.\n결산월을 확인해주세요!");
                            return false;
                        }
                    }
                }
            } else {
                if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                    tmpAcntMM[tmpCnt] = dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i);
                    tmpCnt = tmpCnt + 1;
                }
            }
        }
    }
    if (cmb_ChkCnt == 11) {
        for (var i = 2; i <= 12; i++) {
            if (dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i) != "") {
                dts_af_detail.setCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD1", dts_af_detail.getCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i));
                dts_af_detail.setCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + i, "");
            }
        }
    } else {
        for (var h = 1; h <= 12; h++) {
            dts_af_detail.setCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + h, "");
        }
        for (var k = 1; k <= tmpCnt; k++) {
            dts_af_detail.setCellData(dts_af_detail.getRowPosition(), "ACNTCLS_MMDD" + k, tmpAcntMM[k - 1]);
        }
    }

    //발행기관명(한글), 발행기관명(한글약명), 주소상세 완성형한글 체크
    var urlck = "/CorpInfoAction.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=processCompleteKoreanCheck";
    urlck += "&outputMessageId=INS_CHECK_CLS_COMPLETE_KOREAN";
    urlck += "&COM_NM=" + $c.stf.getObjectValue(txb_ISUR_NM);
    urlck += "&COM_ABBRV=" + $c.stf.getObjectValue(txb_ISUR_ABBRV);
    urlck += "&DTL_ADDR=" + $c.stf.getObjectValue(txb_DTL_ADDR);
    urlck += "&CEO_NM=" + $c.stf.getObjectValue(txb_CEO_NM);
    urlck += "&BZ_REG_IND_NM=" + $c.stf.getObjectValue(txb_ISUR_IND_CONTN);
    urlck += "&BZ_REG_BZCOND_NM=" + $c.stf.getObjectValue(txb_BZCOND_CONTN);
    dts_completeKorean.SyncLoad = "true";
    dts_completeKorean.DataID = encodeURI(urlck);
    dts_completeKorean.Reset();
    var msg = '';
    msg += ' 발행기관(한글명, 한글약명, 상세주소, 대표이사, 업종, 업태)';
    msg += '\n\n 한글표기에 문제가 있습니다. 계속 진행하시겠습니까?';
    msg += '\n\n (시스템담당자에게 문의하시기 바랍니다.)';
    if (dts_completeKorean.getTotalRow() > 0) {
        if (!window.confirm(msg)) {
            processGp = '1';
            return;
        }
    }
    if (!confirm("저장 하시겠습니까?")) {
        return;
    }
    trs_save.Action = "/CorpInfoAction.do?method=registerCorpIssInstEditRct" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(O:pReturnOut=dts_Rst,I:pInput=dts_af_detail)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm + ",EMAIL=" + js_email;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : fn_GetParam
 * 설명       : 전달값을 정의한다.
 ***********************************************/
scwin.arrPar = new Array();
scwin.fn_GetParam = function(arrPar) {
    scwin.arrPar[0] = txb_param1.getValue();
    scwin.arrPar[1] = txb_param2.getValue();

    //alert(arrPar[0] + " " + arrPar[1]);
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    scwin.arrPar, length;
};


/********************************************** 
 * 함수명   : ins_return
 * 설명       : 발행기관 반송 
 ***********************************************/
scwin.ins_return = function() {
    scwin.ins_search();
    dts_bf_detail.removeAll();
    dts_af_detail.removeAll();
};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    $c.cm.PanelToGroupBox(panel_3);
    //PanelToGroupBox(panel_4);
    $c.cm.PanelToGroupBox(panel_3);
    $c.stf.showObj(panel_5, false);
    ins_combo_set(dts_TRANSSTK_AGNT_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00685"); // 00685 - 명의개서회사
    ins_combo_set(dts_COM_ATTR_TP_CD, scwin.vScrenID, SCREN_PROCS_TP_CD_01, "00840"); // 00840 - 회사속성구분코드

    /*
    showObj(txb_OLD_ISUR_NM,false);
    showObj(txb_ISUR_APPL_ID,false);
    showObj(txb_param1,false);
    showObj(txb_param2,false);

    showObj(txb_BF_ACNTCLS_TMP,false);
    showObj(txb_AF_ACNTCLS_TMP,false);

    showObj(txb_BF_MAINTR_BK_CD,false);
    showObj(edt_BF_CAP,false);
    showObj(txb_MAINTR_BK_CD,false);
    showObj(edt_CAP,false);
    showObj(txb_MAIN_TR_BANK_NM,false);
    //showObj(edt_FOUND_DD,false);
    */

    scwin.ins_search();
};
scwin.btn_file_onclick = function() {
    /*
    txb_param1 에는 신청ID
    txb_param2 에는 구분값을 넣는데.. 
    			 + "1 : 발행기관신청, 팩스-발행기관신청 \n"
    			 + "2 : 표준코드신청, 팩스-표준코드신청 \n"
    			 + "3 : 팩스-다운로드IP 로 값을 넣어주세요.\n"
    			 */
    txb_param1.setValue(dts_List.getCellData(dts_List.getRowPosition(), "ISUR_APPL_ID")); // 발행기관  신청 ID  
    txb_param2.setValue("1");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS91100", "첨부파일", "655", "350");
};
scwin.dts_bf_detail_OnLoadCompleted = function(rowcount) {
    var ISUR_CD = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_CD");
    var ISUR_APPL_ID = dts_List.getCellData(dts_List.getRowPosition(), "ISUR_APPL_ID");
    scwin.ins_af_detail(ISUR_CD, ISUR_APPL_ID);
};
scwin.dts_bf_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_bf_detail);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    if (rowcount == 0) return;
    var ISUR_CD = dts_List.getCellData(1, "ISUR_CD");
    var ISUR_APPL_ID = dts_List.getCellData(1, "ISUR_APPL_ID");
    scwin.ins_bf_detail(ISUR_CD, ISUR_APPL_ID);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_bf_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_bf_detail);
};
scwin.dts_af_detail_OnLoadError = function() {
    $c.stf.alert_error(dts_bf_detail);
};
scwin.grd_Grid_OnDblClick = function(row, colid) {
    var ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
    var ISUR_APPL_ID = dts_List.getCellData(row, "ISUR_APPL_ID");
    scwin.ins_bf_detail(ISUR_CD, ISUR_APPL_ID);
};
scwin.dts_checkCoNm_OnLoadCompleted = function(rowcount) {
    var totcnt = 0;
    var msg = "\n상호변경한 기관의 유가증권 중 활성상태인 종목을 발견했습니다.";
    msg += "\n해당 종목의 종목명 변경을 해주십시오.";
    msg += "\n =======================================";
    msg += "\n >>>>> 해당 종목 리스트 <<<<<";
    msg += " =======================================";
    msg += "\n  |  구분  |  표준코드            |  종목명     ";
    msg += "\n =======================================";
    for (var i = 1; i <= rowcount; i++) {
        msg += "\n  |  " + dts_checkCoNm.getCellData(i, "STD_CD_APPL_CONTN_TP_CD");
        msg += "  |  " + dts_checkCoNm.getCellData(i, "STD_CD");
        msg += "  |  " + dts_checkCoNm.getCellData(i, "ISU_NM");
        //		msg += "  |  "+dts_checkCoNm.NameValue(i,"CNT");

        totcnt = eval(totcnt) + eval(dts_checkCoNm.getCellData(i, "CNT"));
    }
    msg += "\n =======================================";
    msg += "\n    합계 : " + totcnt;
    if (rowcount > 0) {
        $c.win.alert(msg);
    }
};
scwin.dts_checkCoNm_OnLoadError = function() {
    $c.stf.alert_error(dts_checkCoNm);
};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
};
scwin.dts_Rst_OnLoadCompleted = async function(rowcount) {
    var RESULT_CONTN = dts_Rst.getCellData(0, "RESULT_CONTN");
    //alert(RESULT_CONTN); 
    if (RESULT_CONTN == "SUCCESS") {

    } else {
        // alert(txb_BF_COM_NM.value+"\n["+RESULT_CONTN +"] 발행기관 코드 수정되었습니다.");

        var rtn = confirm(txb_BF_COM_NM.getValue() + "\n[" + RESULT_CONTN + "] 발행기관 코드 수정되었습니다.\n종목명 변경처리 화면으로 이동하시겠습니까?");
        if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

        {
            //종목명 변경처리 화면으로 이동
            $c.frame.path("/top").WinOpenP("INS20000");
            await $c.frame.CloseFrame();
        }
        //	 ins_search();
        var ISUR_CD = txb_BF_ISUR_CD.getValue();
        var ISUR_APPL_ID = txb_ISUR_APPL_ID.getValue();
        scwin.ins_search();
        dts_bf_detail.removeAll();
        dts_af_detail.removeAll();
        // ins_detail(ISUR_CD,ISUR_APPL_ID);  // 신청 데이터 불러오기 ( 재조회 )

    }
};
scwin.dts_af_detail_OnLoadCompleted = function(rowcount) {
    txb_OLD_ISUR_NM.setValue(txb_BF_COM_NM.getValue());
    var ISUR_CD = txb_BF_ISUR_CD.getValue();
    //alert(ISUR_CD);
    if (txb_BF_COM_NM.getValue() == txb_ISUR_NM.getValue() &&
        txb_BF_COM_ABBRV.getValue() == txb_ISUR_ABBRV.getValue() &&
        txb_BF_COM_ENG_NM.getValue() == txb_ISUR_ENG_NM.getValue() &&
        txb_BF_COM_ENG_ABBRV.getValue() == txb_ISUR_ENG_ABBRV.getValue()) {


    } else {
        scwin.checkCoNm(ISUR_CD);
    }


    /*
    var arrayObj1 = [txb_BF_ISUR_CD, txb_BF_COM_NM, txb_BF_COM_ABBRV, txb_BF_COM_ENG_NM, txb_BF_COM_ENG_ABBRV, txb_BF_BZ_REG_NO
    					, txb_BF_CORP_REG_NO, txb_BF_ZIPCD, txb_BF_ADDR, txb_BF_DTL_ADDR, txb_BF_CEO_NM, txb_BF_HPAGE, txb_BF_CORP_TEL_NO
    					, txb_BF_ENG_ADDR, txb_BF_ENG_DTL_ADDR, txb_BF_LEI_NM, txb_BF_TRANSSTK_AGNT_CD, txb_BF_BZ_REG_BZCOND_NM, txb_BF_BZ_REG_IND_NM, txb_BF_CHRG_NM
    					, txb_BF_CHRG_TEL_NO, txb_BF_CHRG_FAX_NO, txb_BF_ENCRYP_CHRG_EMAIL, edt_BF_FOUND_DD, txb_BF_COM_ATTR_TP_CD, txb_BF_CHRG_INNR_NO];
    					*/
    var arrayObj1 = [txb_BF_ISUR_CD, txb_BF_COM_NM, txb_BF_COM_ABBRV, txb_BF_COM_ENG_NM, txb_BF_COM_ENG_ABBRV, txb_BF_BZ_REG_NO, txb_BF_CORP_REG_NO, txb_BF_ZIPCD, txb_BF_ADDR, txb_BF_DTL_ADDR, txb_BF_CEO_NM, txb_BF_HPAGE, txb_BF_CORP_TEL_NO, txb_BF_ENG_ADDR, txb_BF_ENG_DTL_ADDR, txb_BF_LEI_NM, txb_BF_TRANSSTK_AGNT_CD, txb_BF_BZ_REG_BZCOND_NM, txb_BF_BZ_REG_IND_NM, edt_BF_FOUND_DD, txb_BF_COM_ATTR_TP_CD];

    /*
	var arrayObj2 = [txb_ISUR_CD, txb_ISUR_NM, txb_ISUR_ABBRV, txb_ISUR_ENG_NM, txb_ISUR_ENG_ABBRV, txb_BZ_REG_NO
						, txb_CORP_REG_NO, txb_ZIPCD, txb_ADDR, txb_DTL_ADDR, txb_CEO_NM, txb_HPAGE, txb_TEL_NO
						, txb_ENG_ADDR, txb_ENG_DTL_ADDR, txb_LEI_NM, cmb_TRANSSTK_AGNT_CD, txb_BZCOND_CONTN, txb_ISUR_IND_CONTN, txb_CHRG_NM
						, txb_CHRG_TEL_NO, txb_CHRG_FAX_NO, txb_ENCRYP_CHRG_EMAIL, edt_FOUND_DD, cmb_COM_ATTR_TP_CD, txb_CHRG_INNR_NO];
*/
