scwin.btn_save_onclick = function() {
    scwin.ins_register();
};
scwin.grd_Grid_OnClick = function(row, colid) {
    if (row == 0) return;
    var ISUR_CD = dts_List.getCellData(row, "ISUR_CD");
    var ISUR_APPL_ID = dts_List.getCellData(row, "ISUR_APPL_ID");
    scwin.ins_bf_detail(ISUR_CD, ISUR_APPL_ID);
};
scwin.btn_ret_onclick = function() {
    // 발행기관 신청에서  반송 ret_rsn_flag = 1
    // 발행기관 변경신청 반송 ret_rsn_flag = 2
    // 표준코드 신청  반송 ret_rsn_flag = 3 
    txb_param1.setValue(txb_ISUR_APPL_ID.getValue());
    //alert(txb_param1.value);
    txb_param2.setValue("2");
    fn_GetPar = fn_GetParam;
    ins_popupOpen("", "", "ULDINS90300", "반송처리", "445", "270");
};
scwin.dts_COM_ATTR_TP_CD_OnLoadCompleted = function(rowcount) {
    for (var i = dts_COM_ATTR_TP_CD.getTotalRow(); i > 0; i--) {
        if (dts_COM_ATTR_TP_CD.getCellData(i, "VALUE") == "1") {
            dts_COM_ATTR_TP_CD.setCellData(i, "TEXT", "1 주식회사");
        } else if (dts_COM_ATTR_TP_CD.getCellData(i, "VALUE") == "2") {
            dts_COM_ATTR_TP_CD.setCellData(i, "TEXT", "2 증권투자회사");
        }
    }
};
